use core.files as files
use core.process as process
use core.text as text

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    input :: files.read(path) ?? panic("read failed")
    lines :: input.lines()
    keys := [String]{}
    values := [String]{}
    active := [Bool]{}
    loop line in lines {
        fields :: text.splitn(line, "|", 3)
        if fields.len() != 3 -> panic("malformed record")
        kind :: fields.get(0) ?? panic("malformed record")
        key :: fields.get(1) ?? panic("malformed record")
        value :: fields.get(2) ?? panic("malformed record")
        if kind == "put" {
            found := false
            i := 0
            loop i < keys.len() {
                if active[i] && keys[i] == key {
                    values[i] = ~value
                    found = true
                    break
                }
                i += 1
            }
            if !found {
                keys.push(~key)
                values.push(~value)
                active.push(true)
            }
        } else if kind == "delete" {
            if value != "" -> panic("malformed delete")
            i := 0
            loop i < keys.len() {
                if active[i] && keys[i] == key {
                    active[i] = false
                    break
                }
                i += 1
            }
        } else -> panic("unknown record: {kind}")
    }
    i := 0
    loop i < keys.len() {
        if active[i] -> print("{keys[i]}={values[i]}")
        i += 1
    }
}
